#include "kista/license.hpp"

#include "crypto.hpp"

#include <cstring>
#include <vector>

// The target's key block (spec 0021), generated by kista_sdk_license_keys. Hidden: a reference to it
// is resolved when the module links, to the module's own block, so a target that links the SDK
// without calling the function does not link, even as a shared library that may leave symbols
// undefined (on macOS with -undefined dynamic_lookup it does not load: no module exports a block),
// and never binds to another module's block at load.
#if defined(__GNUC__) || defined(__clang__)
extern "C" __attribute__((visibility("hidden"))) const unsigned char kista_sdk_license_keys[];
#else
extern "C" const unsigned char kista_sdk_license_keys[];
#endif

namespace kista {

namespace {

// The block is read through this pointer, which the compiler cannot fold: the bytes are what the
// build wrote, never constants the optimiser reasoned about.
const unsigned char *volatile key_block = kista_sdk_license_keys;

// The test key's fingerprint (sdk/cpp/test/keys/test-only-2048.pub.pem, the licence vectors' key).
const char *const kTestKid = "sha256:770bd4b7176dd31c2c123d6dc69856fb2a398ea823dcac6f5db7af11d139d552";

// The magic, XORed with 0x5a: the SDK checks the block starts with it without holding it, so the
// magic is in a binary once, in the block.
const unsigned char kMagicX[21] = {0x11, 0x13, 0x09, 0x0e, 0x1b, 0x77, 0x16, 0x13, 0x19, 0x1f, 0x14,
                                   0x09, 0x1f, 0x77, 0x11, 0x1f, 0x03, 0x09, 0x75, 0x6b, 0x5a};

// BlockKeys returns the keys of the block: the generator wrote it, so its layout is taken as
// written, with the magic, the limits and the end marker checked; nothing when they fail.
std::vector<std::string> BlockKeys() {
	const unsigned char *b = key_block;
	for (size_t i = 0; i < sizeof(kMagicX); i++) {
		if ((b[i] ^ 0x5a) != kMagicX[i]) {
			return {};
		}
	}
	size_t p = sizeof(kMagicX);
	unsigned count = b[p++];
	if (count < 1 || count > 4) {
		return {};
	}
	std::vector<std::string> keys;
	for (unsigned i = 0; i < count; i++) {
		size_t len = size_t(b[p]) << 8 | b[p + 1];
		p += 2;
		if (len < 1 || len > 2048) {
			return {};
		}
		keys.emplace_back(reinterpret_cast<const char *>(b + p), len);
		p += len;
	}
	static const char end[] = {'\0', 'K', 'I', 'S', 'T', 'A', '-', 'E', 'N', 'D', '\0'};
	if (std::memcmp(b + p, end, sizeof(end)) != 0) {
		return {};
	}
	return keys;
}

} // namespace

bool TrustsTestKey() {
	return Keys::Trusted().Find(kTestKid) != nullptr;
}

// The block's keys and what is wrong with them, read once.
struct Block {
	Keys keys;
	std::string problem;
};

static const Block &ReadBlock() {
	static const Block block = [] {
		Block bl;
		auto pems = BlockKeys();
		if (pems.empty()) {
			bl.problem = "its licence key block does not parse: it trusts no key";
			return bl;
		}
		for (auto &pem : pems) {
			if (!bl.keys.Add(pem)) {
				bl.problem = "a key in its licence key block is not an RSA-2048 public key with e = 65537, and is skipped";
			}
		}
		if (bl.problem.empty() && bl.keys.Size() != pems.size()) {
			bl.problem = "its licence key block names a key twice";
		}
		return bl;
	}();
	return block;
}

std::string KeyBlockProblem() {
	return ReadBlock().problem;
}

const Keys &Keys::Trusted() {
	return ReadBlock().keys;
}

std::string Fingerprint(const std::string &pem) {
	std::string sum;
	try {
		if (!crypto::IsRSA2048(pem)) {
			return "";
		}
		auto der = crypto::Der(pem);
		// e = 65537, as kista requires (extfile.CheckKey): an RSA SPKI ends with its exponent,
		// INTEGER 65537 (02 03 01 00 01)
		static const std::string e65537("\x02\x03\x01\x00\x01", 5);
		if (der.size() < e65537.size() || der.compare(der.size() - e65537.size(), e65537.size(), e65537) != 0) {
			return "";
		}
		sum = crypto::Sha256(der);
	} catch (const std::exception &) {
		return "";
	}
	static const char hex[] = "0123456789abcdef";
	std::string out = "sha256:";
	for (unsigned char c : sum) {
		out.push_back(hex[c >> 4]);
		out.push_back(hex[c & 0xF]);
	}
	return out;
}

bool Keys::Add(const std::string &pem) {
	auto kid = Fingerprint(pem);
	if (kid.empty()) {
		return false;
	}
	by_kid[kid] = pem;
	return true;
}

const std::string *Keys::Find(const std::string &kid) const {
	auto it = by_kid.find(kid);
	return it == by_kid.end() ? nullptr : &it->second;
}

} // namespace kista
